<?php
declare(strict_types=1);
StudentMigration::requireManage();
$kind=($_REQUEST['kind']??'BALANCES')==='GRADES'?'GRADES':'BALANCES';
$identityOnly=($_GET['action']??'')==='template'&&($_GET['kind']??'')==='BLANK';$id=(int)($_GET['id']??0);
$sy=is_string($_GET['sy']??null)?$_GET['sy']:'';$yl=is_string($_GET['year']??null)?$_GET['year']:'';$section=is_string($_GET['section']??null)?$_GET['section']:'';
if(($_GET['action']??'')==='template'){
    if(!$identityOnly)StudentMigration::requireKind($kind);
    $headers=$identityOnly?['Student ID','Full Name']:StudentMigration::headers($kind);$rows=[$headers];$prefilled=$identityOnly||($_GET['mode']??'')==='students';
    if($prefilled)foreach(GS::students() as $s){$sec=!empty($s['sectionId'])?GS::get('sections',$s['sectionId']):null;
        if(($sy&&($s['schoolYear']??($sec['schoolYear']??''))!==$sy)||($yl&&($s['yearLevel']??($sec['yearLevel']??''))!==$yl)||($section&&($s['sectionId']??'')!==$section))continue;
        $row=array_fill(0,count($headers),'');$row[0]=$s['studentId'];$row[1]=$s['studentName'];$rows[]=$row;
    }
    if($prefilled&&count($rows)===1)throw new AppError('No students match these filters. Change the filters or choose the blank template.');
    if(count($rows)>1001)throw new AppError('Narrow the filters to 1,000 students or fewer.');
    if($identityOnly)Xlsx::download('AcadLink-BLANK-students.xlsx',['Records'=>$rows]);
    $fees=Db::all('SELECT c.name AS category,l.name AS fee FROM sis_fee_labels l JOIN sis_fee_categories c ON c.id=l.category_id WHERE l.is_active=1 AND c.is_active=1 ORDER BY c.name,l.name');
    $subjects=GS::all('subjects');$choices=[2=>GS::schoolYears(),3=>YEAR_LEVELS,4=>TERMS];
    if($kind==='BALANCES'){$choices[7]=array_column($fees,'category');$choices[8]=array_column($fees,'fee');}else{$choices[7]=array_column($subjects,'subjectCode');$choices[11]=['percent','point5'];}
    $example=$kind==='BALANCES'?['2026-001','Dela Cruz, Juan','2025-2026','1st Year','2nd Semester','BSIT 1A','OLD-LEDGER-001','Tuition','Tuition Fee','3000.00']:['2026-001','Dela Cruz, Juan','2025-2026','1st Year','2nd Semester','BSIT 1A','TRANSCRIPT-001','MATH101','Mathematics','3','85','percent'];
    Xlsx::download('AcadLink-'.$kind.'-'.($prefilled?'students':'blank').'.xlsx',['Records'=>$rows,'Instructions'=>[
      ['Step','Instruction'],['1','Student ID must match an existing SIS record. Full Name is checked, never used to merge students.'],['2','School Year, Year Level, Term and Section describe the ORIGINAL historical period.'],['3','One balance row per fee and source reference; enter the REMAINING unpaid amount only, without commas or currency symbols.'],['4','Do not enter historical payments as new receipts. Keep the stable ledger/source Migration Reference when correcting a file.'],['5','Use active SIS categories, fee names and subject codes. Unknown choices must be mapped in the existing setup before upload.'],['6','Complete the Records sheet only. Example and lookup sheets are not imported. Empty prefilled rows with no fee/subject details are ignored.'],['7','Grades: choose percent (0–100, passing 75) or point5 (1–5, passing 3 or better). INC and DRP are supported.'],['8','Upload up to 1,000 rows. Preview changes no live data. Accounting approves balances; Registrar approves grades.'],['9','An existing assessment or finalized grade period is blocked to avoid duplicates. Use authorized corrections instead.']],
      'Example'=>[$headers,$example],'Fee lookup'=>array_merge([['Fee Category','Fee Name']],array_map(fn($r)=>[$r['category'],$r['fee']],$fees)),
      'Subject lookup'=>array_merge([['Subject Code','Subject Name','Units']],array_map(fn($s)=>[$s['subjectCode']??'',$s['subjectName']??'',$s['units']??''],$subjects))],$choices);
}
if(($isPost?($_POST['action']??''):($_GET['action']??''))==='results'){
    $batch=StudentMigration::batch($id);$review=json_decode($batch['review_json'],true);$records=[StudentMigration::headers($batch['kind'])];$issues=[['Excel Row','Result','Error','Warning']];
    foreach($review as $row){$raw=$row['input'];$records[]=array_map(fn($h)=>(string)($raw[$h]??''),StudentMigration::headers($batch['kind']));$issues[]=[$row['row'],$row['error']?'Needs correction':$batch['status'],$row['error'],$row['warning']];}
    Xlsx::download('migration-'.$id.'-results.xlsx',['Records'=>$records,'Validation'=>$issues]);
}
if($isPost){$action=(string)($_POST['action']??'');
    if($action==='upload'){$file=$_FILES['file']??[];if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new AppError('Choose a complete Excel file smaller than the PHP upload limit.');$id=StudentMigration::upload($kind,$file['tmp_name'],$file['name']);flash('success','File checked. Review this batch before approval. No live records were imported.');}
    elseif($action==='approve'){StudentMigration::approve($id,(string)($_POST['reason']??''),isset($_POST['warnings_verified']),(int)($_POST['equity']??0));flash('success','Batch approved. Review the totals, then import.');}
    elseif($action==='import'){StudentMigration::import($id);flash('success','Migration completed. Check the history and accounting entries below.');}
    elseif($action==='reverse'){StudentMigration::reverse($id,(string)($_POST['reason']??''));flash('success','Batch reversed. Original source and audit records were retained.');}
    elseif($action==='discard'){$b=StudentMigration::batch($id);if(!StudentMigration::canApprove($b['kind'])&&(int)$b['created_by']!==Auth::id())throw new Forbidden('Only the creator or authorized reviewer can discard this batch.');$reason=trim((string)($_POST['reason']??''));if(mb_strlen($reason)<8)throw new AppError('Give a discard reason of at least 8 characters.');Db::tx(function()use($id,$reason){$b=Db::one('SELECT status FROM sis_migration_batches WHERE id=? FOR UPDATE',[$id]);if(!in_array($b['status'],['DRAFT','APPROVED'],true))throw new AppError('Imported records must be reversed, not discarded.');Db::q("UPDATE sis_migration_batches SET status='DISCARDED',review_reason=? WHERE id=?",[$reason,$id]);Audit::log('migration_discarded','migration',$id,['reason'=>$reason]);});flash('success','Unposted batch discarded.');}
    else throw new AppError('Unknown migration action.');
    redirect('migration',['id'=>$id]);
}
$batch=$id?StudentMigration::batch($id):null;$review=$batch?json_decode($batch['review_json'],true):[];
$errors=count(array_filter($review,fn($r)=>$r['error']!==''));$warnings=count(array_filter($review,fn($r)=>trim($r['warning'])!==''));
$total=array_sum(array_map(fn($r)=>(int)($r['data']['cents']??0),$review));
$levelPairs=[];foreach(GS::students() as $student){$school=(string)($student['schoolYear']??'');$level=(string)($student['yearLevel']??'');$levelPairs[$school.'|'.$level]=[$school,$level];}
layout_start('Data Migration');page_title('Data Migration','','Import existing unpaid fee balances or reviewed historical academic records.');
?>
<?php if(ImportAll::can()): ?><section class="form-section d-flex flex-wrap align-items-center gap-2 border-primary"><div class="me-auto"><h2 class="h5 mb-1"><i class="bi bi-cloud-upload me-1" aria-hidden="true"></i>Import All</h2><p class="small mb-0">Bulk import subjects, prices per unit, fee templates, teachers and curriculum from one Excel file, with a preview, per-row Add / Skip / Update / Replace and an import history.</p></div><a class="btn btn-primary" href="<?= url('importall') ?>">Open Import All</a></section><?php endif; ?>
<?php if($batch): ?><section class="form-section"><h2 class="h5">Batch #<?= $id ?> · <?= h($batch['kind']) ?> <?= badge($batch['status']) ?></h2><p><?= h($batch['source_name']) ?> · <?= count($review) ?> rows · <?= $errors ?> errors · <?= $warnings ?> warnings<?= $batch['kind']==='BALANCES'?' · Total ₱'.Money::fmt($total):'' ?></p>
<p class="alert alert-info py-2" role="status"><?php
$reviewer=$batch['kind']==='BALANCES'?'Accounting':'Registrar';
echo h(match($batch['status']){'DRAFT'=>$errors?'Correct the reported rows and upload the corrected workbook.':'Waiting for '.$reviewer.' review and approval.','APPROVED'=>'Approved. The authorized reviewer can now import these records.','IMPORTED'=>'Completed. View the student history or download the full results.','REVERSED'=>'Reversed. Original source records and audit history were retained.','DISCARDED'=>'Unposted batch discarded. Upload a corrected workbook when ready.',default=>'Review this batch.'});
?></p>
<p class="small">Balances debit Accounts Receivable and credit the reviewed opening-balance equity account. They do not create receipts or current-year enrollment counts.</p>
<form method="post" class="mb-3"><?= csrf_field() ?><button name="action" value="results" class="btn btn-outline-primary">Download results / correction workbook</button></form>
<div class="table-responsive"><table class="table table-sm"><thead><tr><th>Excel row</th><th>Student</th><th>Period</th><th>Item</th><th>Amount / Grade</th><th>Validation</th></tr></thead><tbody><?php foreach($review as $row):$d=$row['data']??[]; ?><tr><td><?= (int)$row['row'] ?></td><td><?= h(($row['input']['Student ID']??'').' · '.($d['student_name']??($row['input']['Full Name']??''))) ?></td><td><?= h(($row['input']['School Year']??'').' · '.($row['input']['Year Level']??'').' · '.($row['input']['Term']??'')) ?></td><td><?= h($row['input'][$batch['kind']==='BALANCES'?'Fee Name':'Subject Code']??'') ?></td><td><?= h($row['input'][$batch['kind']==='BALANCES'?'Outstanding Balance':'Final Grade']??'') ?></td><td class="<?= $row['error']?'text-danger':'text-muted' ?>"><?= h($row['error']?:($row['warning']?:'Ready')) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if($batch['status']==='DRAFT'&&StudentMigration::canApprove($batch['kind'])): ?><form method="post" class="mt-3" data-loading-label="Reviewing migration…"><?= csrf_field() ?><input type="hidden" name="action" value="approve"><?php if($batch['kind']==='BALANCES'): ?><label class="form-label">Opening-balance equity account</label><select name="equity" class="form-select mb-2" required><option value="">Choose an equity account</option><?php foreach(Accounting::accounts(true) as $acc)if($acc['type']==='EQUITY'): ?><option value="<?= (int)$acc['id'] ?>"><?= h($acc['code'].' · '.$acc['name']) ?></option><?php endif; ?></select><?php endif; ?><label class="form-label">Review reason / source verification</label><input name="reason" class="form-control mb-2" required minlength="8" maxlength="1000"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="warnings_verified"> I verified the source records, Student IDs, name differences and any separate references for repeated fees.</label><button class="btn btn-primary"<?= $errors?' disabled':'' ?>>Approve batch</button></form><?php endif; ?>
<?php if($batch['status']==='APPROVED'&&StudentMigration::canApprove($batch['kind'])): ?><form method="post" data-confirm="Import this approved batch into the live records?" data-loading-label="Importing approved records…"><?= csrf_field() ?><button name="action" value="import" class="btn btn-primary">Import approved records</button></form><p class="small mt-2">Please wait. If interrupted, reopen this batch to check its status. Repeating this same batch cannot import it twice.</p><?php endif; ?>
<?php if(in_array($batch['status'],['DRAFT','APPROVED','IMPORTED'],true)): ?><details class="mt-3"><summary><?= $batch['status']==='IMPORTED'?'Reverse imported batch':'Discard unposted batch' ?></summary><form method="post" class="mt-2" data-confirm="Proceed with this migration correction?"><?= csrf_field() ?><input name="reason" class="form-control mb-2" required minlength="8" maxlength="1000" placeholder="Correction reason"><button class="btn btn-outline-danger" name="action" value="<?= $batch['status']==='IMPORTED'?'reverse':'discard' ?>"><?= $batch['status']==='IMPORTED'?'Reverse batch':'Discard batch' ?></button></form></details><?php endif; ?>
<?php foreach(Db::all('SELECT * FROM sis_migration_targets WHERE batch_id=?',[$id]) as $t):if($t['kind']==='REGISTRATION'){$r=Registration::get((int)$t['target_id']);echo '<p><a href="'.url('history',['id'=>$r['student_doc_id'],'tab'=>'assessments']).'">'.h($r['student_number'].' · '.$r['reg_no']).' — view assessment history</a></p>';}else{$g=GS::get('gradeCompletions',$t['target_id']);if($g)echo '<p><a href="'.url('history',['id'=>$g['studentId'],'tab'=>'grades']).'">'.h($g['studentNumber']).' — view grade history</a></p>';}endforeach; ?></section><?php endif; ?>
<div class="row g-3"><div class="col-lg-6"><section class="form-section"><h2 class="h5">1. Download Excel template</h2><form method="get" id="migrationTemplate" data-levels="<?= h(json_encode(array_values($levelPairs),JSON_THROW_ON_ERROR)) ?>"><input type="hidden" name="r" value="migration"><input type="hidden" name="action" value="template"><label class="form-label">Record type</label><select name="kind" class="form-select mb-2"><option value="BALANCES">Itemized previous balances</option><option value="GRADES">Previous academic records</option><option value="BLANK">Blank — Student ID and Name only</option></select><label class="form-label">Student details</label><select name="mode" class="form-select mb-2"><option value="students">Include Student IDs and full names</option><option value="blank">Blank template</option></select><p class="small text-muted" id="migrationBlankHint" hidden>Downloads only Student ID and Full Name for students matching the filters. Choose balances or academic records for an import template.</p><label class="form-label">School year filter</label><select name="sy" class="form-select mb-2"><?= sy_options($sy,true) ?></select><label class="form-label">Year level filter</label><select name="year" class="form-select mb-2"><?= list_options(YEAR_LEVELS,$yl,'All year levels') ?></select><label class="form-label">Section filter</label><select name="section" class="form-select mb-3"><option value="">All sections</option><?php foreach(GS::sections() as $sec): ?><option value="<?= h($sec['id']) ?>" data-school-year="<?= h($sec['schoolYear']) ?>" data-year-level="<?= h($sec['yearLevel']) ?>"><?= h($sec['schoolYear'].' · '.$sec['yearLevel'].' · '.$sec['sectionName']) ?></option><?php endforeach; ?></select><button class="btn btn-primary">Download template</button></form></section></div>
<div class="col-lg-6"><section class="form-section"><h2 class="h5">2. Upload and validate</h2><form method="post" enctype="multipart/form-data" action="<?= url('migration') ?>" data-loading-label="Reading file and validating records…"><?= csrf_field() ?><input type="hidden" name="action" value="upload"><label class="form-label">Record type</label><select name="kind" class="form-select mb-3"><option value="BALANCES">Itemized previous balances</option><option value="GRADES">Previous academic records</option></select><label class="form-label">Completed template</label><input type="file" name="file" class="form-control mb-3" accept=".xlsx,.csv" required><p class="small">Up to 1,000 completed rows / 5 MB. Importing creates no new student accounts. Unknown students or fees must be verified in SIS first.</p><button class="btn btn-primary">Upload and check</button></form></section></div></div>
<section class="form-section"><h2 class="h5">Recent batches</h2><div class="table-responsive"><table class="table"><thead><tr><th>Batch</th><th>Source</th><th>Type</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach(RecordList::query("SELECT id,source_name,kind,status,created_at FROM sis_migration_batches".(Auth::can('registration','users.manage')?'':" WHERE kind='BALANCES'")." ORDER BY id DESC LIMIT 100") as $b): ?><tr><td><a href="<?= url('migration',['id'=>$b['id']]) ?>">#<?= $b['id'] ?></a></td><td><?= h($b['source_name']) ?></td><td><?= h($b['kind']) ?></td><td><?= badge($b['status']) ?></td><td><?= h($b['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
